export const withdrawMeMutationKey = (options?: Partial<Options<WithdrawMeData>>) => createMutationKey('withdrawMe', options);

/**
 * 회원 즉시 탈퇴 요청
 *
 * 현재 비밀번호와 고정 확인 문구를 검증한 뒤 계정을 즉시 PURGING 상태로 전환합니다. 이후 인증을 차단하고 기존 작품 영구 삭제 파이프라인으로 모든 작품을 비동기 파기한 뒤 회원 행을 복구 불가능하게 삭제합니다.
 */
export const withdrawMeMutation = (options?: Partial<Options<WithdrawMeData>>): UseMutationOptions<WithdrawMeResponse, WithdrawMeError, Options<WithdrawMeData>> => {
    const mutationOptions: UseMutationOptions<WithdrawMeResponse, WithdrawMeError, Options<WithdrawMeData>> = {
        mutationFn: async (fnOptions) => {
            const { data } = await withdrawMe({
                ...options,
                ...fnOptions,
                throwOnError: true
            });
            return data;
        },
        mutationKey: withdrawMeMutationKey(options)
    };
    return mutationOptions;
};
